from langfuse import observe
from langfuse._client.attributes import LangfuseOtelSpanAttributes

def _finished_spans_by_name(memory_exporter, name):
    return [s for s in memory_exporter.get_finished_spans() if s.name == name]

def test_observe_extra_attributes_are_set(langfuse_memory_client, memory_exporter):
    @observe(name="extra_span", extra_attributes={"my_key": "my_val"})
    def fn():
        return 42

    assert fn() == 42
    langfuse_memory_client.flush()
    span = _finished_spans_by_name(memory_exporter, "extra_span")[0]
    assert span.attributes.get("my_key") == "my_val"
